{
  "sop_id": "SOP-013",
  "title": "Bill of Quantities (BOQ) Review",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Check BOQ completeness",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Verify quantities against drawings and rates against schedule of rates",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Summarize variance, list non-standard items, and submit BOQ",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Wait for drawings revision or take-off confirmation from Operations",
      "role": "System",
      "type": "intake"
    },
    {
      "step_id": "A1",
      "name": "Incharge approval",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Correct and resubmit after rejection",
      "role": "Executor",
      "type": "rework"
    },
    {
      "step_id": "A2",
      "name": "Lead approval (for exceptions)",
      "role": "Lead",
      "type": "approval"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "if BOQ is high value, high variance, or has many non-standard items"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Operations",
      "item": "Drawings revision or take-off confirmation",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.90
}
